'=>'Bewerken','delete'=>'Verwijderen','confirm'=>'Deze property verwijderen?','no'=>'Geen properties gevonden','no_text'=>'Pas je zoekopdracht aan of maak je eerste property aan.','total'=>'Totaal','active'=>'Gepubliceerd','drafts'=>'Concepten','sales'=>'Te koop','rentals'=>'Te huur','employees'=>'Medewerkers','sign_out'=>'Uitloggen','language'=>'Taal']][$lang];
