$where=['p.deleted_at IS NULL'];$params=[];if(!$auth->isSuperAdmin()){if(!$officeId){http_response_code(403);exit('No office is assigned to this account.');}$where[]='p.office_id=:office_id';$params['office_id']=(int)$officeId;}
