$sql='SELECT p.id,p.reference,p.status,p.transaction_type,p.title,p.price,p.currency_code,p.living_area_m2,p.land_area_m2,p.bedrooms,p.bathrooms,p.city,p.postcode,p.updated_at,o.name office_name,pt.code property_type,pm.file_path primary_image,pm.thumbnail_path primary_thumbnail FROM properties p INNER JOIN offices o ON o.id=p.office_id LEFT JOIN property_types pt ON pt.id=p.property_type_id LEFT JOIN property_media pm ON pm.id=(SELECT pm2.id FROM property_media pm2 WHERE pm2.property_id=p.id AND pm2.media_type="photo" AND pm2.deleted_at IS NULL ORDER BY pm2.is_primary DESC,pm2.sort_order ASC,pm2.id ASC LIMIT 1) WHERE '.implode(' AND ',$where).' ORDER BY p.updated_at DESC,p.id DESC';$s=$db->prepare($sql);$s->execute($params);$properties=$s->fetchAll();
$countWhere=['p.deleted_at IS NULL'];$cp=[];if(!$auth->isSuperAdmin()){$countWhere[]='p.office_id=:coffice';$cp['coffice']=(int)$officeId;}$count=$db->prepare('SELECT COUNT(*) FROM properties p WHERE '.implode(' AND ',$countWhere));$count->execute($cp);$total=(int)$count->fetchColumn();$pub=$db->prepare('SELECT COUNT(*) FROM properties p WHERE '.implode(' AND ',$countWhere).' AND p.is_published=1');$pub->execute($cp);$published=(int)$pub->fetchColumn();$dr=$db->prepare('SELECT COUNT(*) FROM properties p WHERE '.implode(' AND ',$countWhere)." AND p.status='draft'");$dr->execute($cp);$drafts=(int)$dr->fetchColumn();$sa=$db->prepare('SELECT COUNT(*) FROM properties p WHERE '.implode(' AND ',$countWhere)." AND p.transaction_type='sale'");$sa->execute($cp);$sales=(int)$sa->fetchColumn();$re=$db->prepare('SELECT COUNT(*) FROM properties p WHERE '.implode(' AND ',$countWhere)." AND p.transaction_type='rent'");$re->execute($cp);$rentals=(int)$re->fetchColumn();
