<!doctype html><html lang="<?=e($lang)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($t['property'])?> — <?=e($officeName)?></title><link rel="stylesheet" href="<?=e($base)?>/assets/css/dashboard.css"><link rel="stylesheet" href="<?=e($base)?>/assets/css/properties.css"><style>.transaction-stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:9px}.transaction-stat-grid>div+div{border-left:1px solid #edf0f2;padding-left:18px}.transaction-stat-grid strong{margin:0 0 4px}.transaction-stat-grid small{display:block}@media(max-width:760px){.transaction-stat-grid{gap:10px}.transaction-stat-grid>div+div{padding-left:10px}}</style></head><body><div class="app-shell"><?php require __DIR__ . '/../admin/_sidebar.php'; ?><main class="main">
