><?=e($t['delete'])?></button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$properties):?><div class="empty"><strong><?=e($t['no'])?></strong><span><?=e($t['no_text'])?></span></div><?php endif;?></div></div>
